let state=initialState(),queue=Promise.resolve(),route=location.hash.slice(1)||'workout',previous=null,imported=null,saveError=null,photoURLs=[],restEnd=0,restInterval,lastDialogTrigger=null;
const app=document.querySelector('#app');
