 'check-all':async b=>{await queued(s=>{for(const a of exerciseById(s,b.dataset.id).entries){if(a.kg===null||a.reps===null||a.reps<1)throw Error('Enter a load and reps for every set before checking all.');a.done=true;if(a.skipped)a.skipped=false;}});closeDialog();},
