 'toggle-set':async b=>{let checked=false;await queued(s=>{const a=exerciseById(s,b.dataset.id).entries.find(x=>x.id===b.dataset.set);if(!a.done&&(a.kg===null||a.reps===null||a.reps<1))throw Error('Enter a load and at least one repetition first. For unweighted bodyweight sets, enter 0.');a.done=!a.done;if(a.done&&a.skipped)a.skipped=false;if(!a.done)s.draft.activeSetId=a.id;checked=a.done;});if(checked&&state.upgrade?.haptics&&navigator.vibrate)navigator.vibrate(25);if(checked&&state.profile.timer)startRest(b.dataset.id);},
 'set-type':b=>{const e=exerciseById(state,b.dataset.id);const a=e.entries.find(a=>a.id===b.dataset.set);dialog('Set type',`<p>Warm-ups are recorded separately and excluded from progression and working-set totals.</p><div class="stack">${!a.done?button('Make this the current set','select-active-set','primary',`data-id="${e.id}" data-set="${a.id}"`)+button(a.skipped?'Return this set to workout':'Skip this set (keep values)','skip-set','secondary',`data-id="${e.id}" data-set="${a.id}"`):''}${['working','warmup','drop','failure'].map(t=>button(t[0].toUpperCase()+t.slice(1),'choose-type',a.type===t?'primary':'secondary',`data-id="${e.id}" data-set="${a.id}" data-value="${t}"`)).join('')}</div>`);},
 'choose-type':async b=>{await queued(s=>{exerciseById(s,b.dataset.id).entries.find(a=>a.id===b.dataset.set).type=b.dataset.value;});closeDialog();},
 'apply-rec':async b=>{await queued(s=>{const e=exerciseById(s,b.dataset.id);const r=recFor(e);if(r.kg===null)return;for(const a of e.entries.filter(a=>!a.done))a.kg=r.kg;});notify('Suggested load applied to unfinished sets. Edit it any time.');},
 readiness:async b=>queued(s=>{s.draft.readiness=s.draft.readiness===Number(b.dataset.value)?null:Number(b.dataset.value);}),
 discard:()=>confirmAction('Discard this draft?','Your saved workouts will remain. You can undo this discard in Settings.','confirm-discard'),
 'confirm-discard':async()=>{await queued(s=>{s.draft=null;},{undo:true});closeDialog();},
 finish:async()=>{await queue;const w=state.draft;if(!w.exercises.some(e=>e.entries.some(a=>a.done)))throw Error('Complete at least one set before saving the workout.');const incomplete=w.exercises.some(e=>e.entries.some(a=>!a.done&&!a.skipped));if(incomplete)confirmAction('Finish with incomplete sets?','Only checked sets will count toward recommendations and analytics. Unchecked values are preserved in history for reference.','confirm-finish');else await finishWorkout();},
 'confirm-finish':finishWorkout,
 'session-details':()=>dialog('Session details',`<form id="session-form">${field('Workout name',`<input name="name" required maxlength="80" value="${esc(state.draft.name)}">`)}${field('Training date',`<input name="date" type="date" required max="${today()}" value="${state.draft.date}">`)}${field('Session notes',`<textarea name="notes" maxlength="3000">${esc(state.draft.notes)}</textarea>`)}<button class="primary" type="submit">Save details</button></form>`),
 'exercise-details':b=>{const e=exerciseById(state,b.dataset.id);dialog('Targets & notes',`<form id="exercise-form" data-id="${e.id}"><div class="form-grid three">${field('Target sets',`<input name="sets" type="number" min="1" max="12" value="${e.sets}" required>`)}${field('Min reps',`<input name="min" type="number" min="1" max="100" value="${e.min}" required>`)}${field('Max reps',`<input name="max" type="number" min="1" max="100" value="${e.max}" required>`)}</div>${field('Exercise notes',`<textarea name="notes" maxlength="1000">${esc(e.notes)}</textarea>`)}<p class="muted">Changing target sets does not add or delete logged sets. Use Add set / Remove set.</p><button type="submit" class="primary">Save targets</button></form>`);},
 'edit-session':async b=>{if(state.draft)throw Error('Finish or discard the active draft before editing history.');await queued(s=>{const w=structuredClone(s.sessions.find(w=>w.id===b.dataset.id));w.editingId=w.id;s.draft=w;});go('workout');},
 'delete-session':b=>confirmAction('Delete this session?','This removes it from your training history and future recommendations. You can undo this deletion.','confirm-delete-session',`data-id="${b.dataset.id}"`),
 'confirm-delete-session':async b=>{await queued(s=>{if(s.draft?.editingId===b.dataset.id)throw Error('Close the edit draft first.');s.sessions=s.sessions.filter(w=>w.id!==b.dataset.id);},{undo:true});closeDialog();notify('Workout deleted. Undo is available in Settings.');},
 undo:async()=>{if(!previous)return;const restored=previous;await queued(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,restored);});previous=null;render();notify('Last deletion undone.');},
 'custom-exercise':()=>customEditor(),
